corpus_block("test-geom-sf.R: geom_sf() determines the legend type from mapped geometry column", {
  skip_if_not_installed("sf")
  p1 <- rbind(c(1,1), c(2,2), c(3,3))
  s1 <- rbind(c(0,3), c(0,4), c(1,5), c(2,5))
  s2 <- rbind(c(0.2,3), c(0.2,4), c(1,4.8), c(2,4.8))
  s3 <- rbind(c(0,4.4), c(0.6,5))
  d_sf <- sf::st_sf(
      g_point = sf::st_sfc(sf::st_multipoint(p1)),
      g_line = sf::st_sfc(sf::st_multilinestring(list(s1, s2, s3))),
      v = "a"
    )
  .plot("test-geom-sf.R: geom_sf() determines the legend type from mapped geometry column #1", ggplot(d_sf) + geom_sf(aes(geometry = g_point, colour = "a")))
  p <- ggplot_build(
      ggplot(d_sf) + geom_sf(aes(geometry = g_point, colour = "a"))
    )
  .plot("test-geom-sf.R: geom_sf() determines the legend type from mapped geometry column #2", ggplot(d_sf) + geom_sf(aes(geometry = g_line, colour = "a")))
  p <- ggplot_build(
      ggplot(d_sf) + geom_sf(aes(geometry = g_line, colour = "a"))
    )
})

