corpus_block("test-geom-sf.R: geom_sf draws correctly", {
  skip_if_not_installed("sf")
  nc_tiny_coords <- matrix(
      c(-81.473, -81.741, -81.67, -81.345, -81.266, -81.24, -81.473,
        36.234, 36.392, 36.59, 36.573, 36.437, 36.365, 36.234),
      ncol = 2
    )
  nc <- sf::st_as_sf(
      data_frame(
        NAME = "ashe",
        geometry = sf::st_sfc(sf::st_polygon(list(nc_tiny_coords)), crs = 4326)
      )
    )
  pts <- sf::st_sf(a = 1:2, geometry = sf::st_sfc(sf::st_point(0:1), sf::st_point(1:2)))
  .plot("test-geom-sf.R: geom_sf draws correctly #1", plot <- ggplot() + geom_sf(data = pts))
  .plot("test-geom-sf.R: geom_sf draws correctly #2", ggplot() + geom_sf(data = nc, linetype = 2) + coord_sf(datum = 4326))
  pts <- sf::st_sf(a = 1:2, geometry = sf::st_sfc(sf::st_point(0:1), sf::st_point(1:2)))
  .plot("test-geom-sf.R: geom_sf draws correctly #3", ggplot() + geom_sf(data = pts))
})

